shop.yml:
# Mainplugins Sklep - ustawienia. Przedmioty i ceny są w categories/<id>.yml (jeden plik na kategorię).
# Teksty (tytuły, przyciski, wiadomości) są w lang/en.yml i lang/pl.yml.
# Wczytanie bez restartu: /@shop reload

# Kolejność kategorii w menu głównym (nazwy plików z categories/ bez .yml).
categories: [blocks, farming, ores, mob-drops, food]

# Jak zaokrąglać ceny, gdy gracz kupuje część paczki albo ceny dynamiczne je zmieniają:
#   whole = pełne złotówki (1 sztuka z paczki "64 za 10" kosztuje 1)
#   cents = grosze (1 sztuka z paczki "64 za 10" kosztuje 0.16)
price-rounding: cents

# Ceny skupu reagują na sprzedaż: dużo sprzedaży -> cena spada, nikt nie sprzedaje -> rośnie.
dynamic-prices:
  enabled: true
  cycle-minutes: 60        # co ile minut przeliczać ceny
  min-multiplier: 0.5      # najniższy skup = 50% zwykłego
  max-multiplier: 1.5      # najwyższy skup = 150% zwykłego
  reset-days: 14           # co tyle dni wszystkie ceny wracają do normy
  max-sell-share: 0.9      # skup nigdy nie daje więcej niż 90% ceny kupna

# Statystyki sprzedaży (stats.yml + stats.csv do Excela) z podpowiedziami, które ceny zmienić.
stats:
  enabled: false

# Co leży gdzie w każdym oknie. size = 9, 18, 27, 36, 45 albo 54.
# Role: CATEGORY_SLOT (menu główne), ITEM_SLOT, AMOUNT_SLOT (wybór ilości, amount = sztuki),
#       NAV_BACK, NAV_PREV, NAV_NEXT, EXIT, SEARCH, SORT, FILLER (opcjonalnie material).
